import openpyxl
wb = openpyxl.load_workbook('output.xlsx')
for sh in ['Jack','Henry','Richard']:
    ws = wb[sh]
    yellow_cols = set()
    yellow_cells = {}
    for row in ws.iter_rows():
        for cell in row:
            fill = cell.fill
            rgb = None
            if fill and fill.patternType:
                rgb = fill.fgColor.rgb
            if rgb and rgb not in ('00000000',) and fill.patternType:
                yellow_cols.add(cell.column)
                yellow_cells.setdefault(cell.column, []).append(cell.coordinate)
    print(sh, 'yellow cols:', sorted(yellow_cols))
    for c in sorted(yellow_cells):
        print('  col', c, yellow_cells[c][:5])
